<script setup lang="ts">
import { t } from '@/i18n';
import { onMounted, reactive, ref } from 'vue'; import { useRoute, useRouter } from 'vue-router'; import { api } from '@/app/runtime'; import { useAsync } from '@/composables/useAsync'; import type { ExhibitionDetail } from '@/api/types';
const route = useRoute(); const router = useRouter(); const query = useAsync<ExhibitionDetail>(); const error = ref(''); const saving = ref(false); const form = reactive({ title: '', venue: '', date: '', time: '', category: '', status: 'optional', description: '', descriptionFormat: 'markdown' });
onMounted(async () => { if (route.params.id) { const data = await query.run(() => api.exhibitions.get(String(route.params.id))); if (data?.exhibition) Object.assign(form, data.exhibition); } });
async function save() { error.value = ''; saving.value = true; try { await api.exhibitions.save({ ...form, ...(route.params.id ? { id: String(route.params.id) } : {}) }); await router.replace('/exhibitor'); } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } finally { saving.value = false; } }
</script>
<template><section class="page"><button class="text-action" @click="router.back()">{{ t('s_omytgn') }}</button><h1>{{ route.params.id ? t('s_eutzzb') : t('s_p9fllo') }}</h1><form class="card form" @submit.prevent="save"><label>{{ t('s_hzx914') }}<input v-model="form.title" required maxlength="60"></label><label>{{ t('s_25fwki') }}<input v-model="form.venue" required maxlength="60"></label><label>{{ t('s_14s86i5') }}<input v-model="form.date" required type="date"></label><label>{{ t('s_1f90xvr') }}<input v-model="form.time" required></label><label>{{ t('s_1kbcp7q') }}<input v-model="form.category"></label><label>{{ t('s_1vv5l4v') }}<select v-model="form.status"><option value="optional">{{ t('s_42gtzo') }}</option><option value="review">{{ t('s_1k614zq') }}</option><option value="display">{{ t('s_3ytdpr') }}</option></select></label><label>{{ t('s_15s6uqt') }}<textarea v-model="form.description" rows="8"></textarea></label><p v-if="error" class="error">{{ error }}</p><button class="cta" :disabled="saving">{{ t('s_10q6dxb') }}</button></form></section></template>
